INSERT INTO purpose VALUES('theory-coherent-resolutions','basis::Basis','struct','Holds the confluences and the critical triples of a convergent cell system as one complex, with the matching of the reduction, so the collapse removes each redundant confluence.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','basis::BasisCell','enum','Names a cell of the basis, a confluence or a critical triple, so the collapse reads its class.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','basis::BasisFault','enum','Names why the basis cannot answer, so a refused read of a cell, a move or a fill is told apart.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','basis::BasisRefusal','enum','Names why the basis refuses a cell system, so a copying cell, an unreplayed certificate or an unclosed boundary is reported.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','basis::Composite','enum','Holds a composite of the basis, a homotopy or the 4-cell of a triple, so the equivalence maps it.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','basis::Fill','struct','Holds one confluence of a homotopy replaced through the 4-cell of a triple, so a witness step is replayed.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','basis::Homotopy','struct','Holds a rewriting path and the moves that deform it, so a 3-cell of the free (3,1)-category on the confluences is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','basis::Move','enum','Names one deformation of a rewriting path, a confluence in context, an exchange or a word put in or out, so a homotopy runs.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','basis::PathStep','struct','Holds a cell fired at a position along its cell or against it, so a rewriting path steps.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','basis::RewritePath','struct','Holds a term and the steps that run from it, so a 2-cell of the free (2,1)-category on the cells is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','basis::Sense','enum','Names whether a step or a confluence runs along its cell or against it, so an inverse is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','basis::Witness','struct','Holds fills applied in turn to a composite, so the replay checks that a removed confluence returns through its triple.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::Arity','struct','Names a number of variables, the arity of an operation or the variables of a context, so a count of variables is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::BarDegree','struct','Names the degree of a cell of a bar complex, so the cells of one degree are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::BatchIndex','struct','Names the zero-based position of one batch in an overlap worklist, so a batch''s place is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::BudgetExhaustion','struct','Names whether a normalization stopped at its budget with a redex still pending, so the stop''s kind is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::CertificateIndex','struct','Names the stable key an overlap support assigns a certificate, so a certificate''s place is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::CompletionCellBudget','struct','Names the number of cells a store may hold before completion declines to insert another, so the ceiling''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::CompletionStatus','struct','Names whether a completion run processed its whole worklist rather than declining, so the run''s outcome is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::CompletionStepBudget','struct','Names the number of critical pairs one completion run may process, so the ceiling''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::MovePlace','struct','Names the zero-based place of one move in a homotopy, so a fill''s move is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::NormalizationBudget','struct','Names the number of rewrite steps one normalization may take, so the ceiling''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::Occurrences','struct','Names the occurrences of one variable in a term, so the coefficient of a first face is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::Operation','struct','Names the place of an operation in the signature of a Lawvere theory, so the operation''s arity is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::OverlapIndex','struct','Names the zero-based position of one overlap within its batch, so an overlap''s place is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::PairDecisions','struct','Names how many critical pairs a joining has decided, so a joining''s count is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::RulePlace','struct','Names the place of a rule in the rules of a Lawvere theory, so the rule that an essential overlap names is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::StepIndependence','struct','Names whether two cells, two certificates or two overlaps are independent under an overlap support, so the independence''s verdict is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::StepPlace','struct','Names the zero-based place of one step in a rewriting path, so a move''s offset is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::TermPlace','struct','Names the place of a term in its table, so two terms compare by their places.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::TermSize','struct','Names a number of nodes of a term or of the terms of a cell, so a bound on the size of a cell is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::TraceletEquivalence','struct','Names whether two certificates denote one transformation, so the equivalence''s verdict is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::TraceletReplay','struct','Names whether a certificate replays, so the replay''s verdict is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::TripleIndex','struct','Names the zero-based place of one critical triple in the list that a reduction reads, so a triple''s place is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','boundary::Variable','struct','Names the place of a variable in a context, so a substitution fills it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','completion::CompletionBudget','struct','Holds the three ceilings a completion run may reach, so the run''s limits are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','completion::CompletionOutcome','enum','Names the outcome of a completion run, so the run''s result is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','completion::CompositePair','struct','Holds a critical pair that a joining skips as composite, with the redex below its seam, so its replay checks the skip.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','completion::CompositeRefusal','enum','Names why the witness of a composite pair does not replay, so a forged witness is refused by name.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','completion::DeclineReason','enum','Names why a completion run declined, so the decline''s cause is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','completion::Joinability','enum','Names whether a store''s critical pairs join, so the joinability''s verdict is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','completion::NoScheme','struct','Classes no critical pair, so a joining joins each pair.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','completion::PairClass','enum','Names the class that a scheme gives a critical pair, so a joining skips a composite pair with its witness and joins the others.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','completion::PairJoining','struct','Holds the joinability check over a store a caller grows by appending cells, so the check''s state is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','completion::PairScheme','trait','States the class of each critical pair before a joining decides it, so a joining skips the join of a composite pair.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','completion::SuppliedOverlapError','enum','Names why a supplied overlap was invalid, so the error''s cause is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','completion::complete','function','Runs confluence completion over a store, so the store''s critical pairs are joined or oriented.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','completion::complete_with_overlap_source','function','Runs completion seeded by a caller''s own matcher, so the caller''s overlaps are validated and joined.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','completion::join_critical_pairs','function','Checks whether a store''s critical pairs already join, so the first divergence is reported.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','completion::scheduled_confluence_batches','function','Schedules each root branching of the store once into independent batches, so completion joins each branching once.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','lawvere::Arrow','struct','Holds a morphism of a Lawvere theory, a tuple of normal forms in a context, so a cell of the bar complex is read arrow by arrow.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','lawvere::BarBound','struct','Holds the bound of a truncation, so the largest subcomplex inside it is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','lawvere::BarCell','struct','Holds a cell of the bar complex, a composable list of arrows, so a matching reads the cells of the complex.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','lawvere::Degeneracy','enum','Names whether a cell of the bar complex counts zero, so a degenerate face is dropped.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','lawvere::LawvereError','enum','Names why a Lawvere theory or its bar complex gives no answer, so the refusal''s cause is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','lawvere::LawvereTheory','struct','Holds the Lawvere theory that a first-order block presents, with its normal forms, so its bar complex is read as a complex of the Morse crate.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','lawvere::TermHead','enum','Names the outermost symbol of a term, so a match reads a variable apart from an operation.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','lawvere::TermNode','struct','Holds one node of a term, its symbol and the places of its arguments, so the table interns each term once.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','lawvere::TermTable','struct','Holds the interned terms of one theory, each once after its arguments, so the place of a term is its identity.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','lawvere::Truncation','struct','Holds the cells of the largest subcomplex inside a bound with their faces, so a homology or a matching reads a finite complex.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','lawvere::brown::overlapped','module','Names the reason no rule is named.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','lawvere::root_rewrite','module','Names the reason no rewrite is found.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','lawvere::truncated','module','Names the reason the cell has no entry.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','overlap::Overlap','struct','Holds one unification at a seam, so the overlap''s span is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','overlap::OverlapKind','enum','Names the kind of overlap, so the overlap''s family is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','overlap::OverlapRefusal','enum','Names why an overlap was refused, so the refusal''s cause is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','overlap::OverlapSupport','struct','Holds which cells and which certificates overlap, so the support''s relation is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','overlap::PeakLegs','enum','Names the legs of a peak, so the peak''s shape is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','overlap::enumerate_overlaps','function','Enumerates every unification at a seam for each ordered pair of cells, so the family''s entries are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','overlap::interior_overlaps_between','function','Enumerates the interior overlaps between two cells, so the interior family''s entries are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','overlap::overlaps_between','function','Enumerates the overlaps between two cells, so the pair''s entries are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','overlap::peak_legs','function','Names the legs of a peak, so the peak''s shape is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','overlap::root_overlaps_between','function','Enumerates the root overlaps between two cells, so the root family''s entries are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','rewrite::CellApp','struct','Holds one rewrite step, so the step''s cell, position and substitution are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','rewrite::Normalization','struct','Holds the outcome of a normalization, so the term reached and the budget''s stop are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','rewrite::Rewrite','struct','Holds one successful rewrite, so the step and the term after it are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','rewrite::apply_once','function','Fires the first cell that fires anywhere, so the term''s first redex is contracted.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','rewrite::fire_at','function','Fires a cell at a command position and keeps the substitution that matched, so a step records its evidence.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','rewrite::firing','module','Names the reason the step does not happen.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-coherent-resolutions','rewrite::normalize','function','Repeats firing until no cell fires or the budget is spent, so the term''s normal form is reached.',NULL,'fits','sound',NULL);
